import { Injectable } from '@angular/core';
import { CanLoad, Route, UrlSegment, Router, UrlTree, CanMatchFn } from '@angular/router';
import { Observable } from 'rxjs';
import { AuthService } from '../services/auth.service';

@Injectable({
  providedIn: 'root'
})
export const AuthorizedGuard: CanMatchFn = (
  route: Route,
  segments: UrlSegment[]
): boolean | UrlTree => {
  rn this.router.parseUrl('/login');

}
